/**
 * Voluntary Application Server Identification (RFC 8292): the instance signs each push
 * request with the key pair whose public half the browser subscribed with, so that a push
 * service delivers only what this instance sent.
 *
 *   Authorization: vapid t=<JWT ES256 { aud: push service origin, exp, sub }>, k=<public key>
 *
 * The pair is generated by the instance (`generateVapidKeys`) and sealed under the master
 * key (`vapid-keys.ts`); nothing is configured. `sub` is the instance's public URL: a push
 * service may use it to reach the operator, and it is already public.
 */
import { createPrivateKey, generateKeyPairSync, type KeyObject } from 'node:crypto';

import { SignJWT } from 'jose';

/** RFC 8292 §2: no longer than 24 hours; twelve leaves room for a skewed clock. */
export const VAPID_TOKEN_SECONDS = 12 * 60 * 60;

/** The key pair as the store keeps it: the private JWK; the public key is derived from it. */
export interface VapidKeys {
  /** EC P-256 private key as a JWK (`kty`, `crv`, `x`, `y`, `d`). */
  readonly privateJwk: JsonWebKey;
}

export class VapidKeyError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'VapidKeyError';
  }
}

export function generateVapidKeys(): VapidKeys {
  const { privateKey } = generateKeyPairSync('ec', { namedCurve: 'P-256' });
  return { privateJwk: privateKey.export({ format: 'jwk' }) };
}

/** Parses what the store holds; throws `VapidKeyError` on anything but a P-256 private JWK. */
export function parseVapidKeys(text: string): VapidKeys {
  const value: unknown = JSON.parse(text);
  const jwk =
    typeof value === 'object' && value !== null
      ? (value as { privateJwk?: JsonWebKey }).privateJwk
      : undefined;
  if (
    !jwk ||
    jwk.kty !== 'EC' ||
    jwk.crv !== 'P-256' ||
    typeof jwk.x !== 'string' ||
    typeof jwk.y !== 'string' ||
    typeof jwk.d !== 'string'
  ) {
    throw new VapidKeyError('the stored VAPID key pair is not a P-256 private key');
  }
  return { privateJwk: jwk };
}

/**
 * The public key as a browser takes it for `applicationServerKey` and as the `k` parameter
 * carries it: the uncompressed point `0x04 ‖ x ‖ y`, base64url.
 */
export function vapidPublicKey(keys: VapidKeys): string {
  const { x, y } = keys.privateJwk;
  if (typeof x !== 'string' || typeof y !== 'string') {
    throw new VapidKeyError('the VAPID key pair has no public point');
  }
  return Buffer.concat([
    Buffer.from([0x04]),
    Buffer.from(x, 'base64url'),
    Buffer.from(y, 'base64url'),
  ]).toString('base64url');
}

function privateKeyOf(keys: VapidKeys): KeyObject {
  return createPrivateKey({ key: keys.privateJwk, format: 'jwk' });
}

export interface VapidHeaderInput {
  /** The subscription's endpoint: the token's audience is its origin. */
  readonly endpoint: string;
  /** Who sends: the instance's public URL. */
  readonly subject: string;
  readonly keys: VapidKeys;
  readonly now: Date;
}

/** The `Authorization` header of one push request. */
export async function vapidAuthorization(input: VapidHeaderInput): Promise<string> {
  const audience = new URL(input.endpoint).origin;
  const issuedAt = Math.floor(input.now.getTime() / 1000);
  const token = await new SignJWT({})
    .setProtectedHeader({ typ: 'JWT', alg: 'ES256' })
    .setAudience(audience)
    .setExpirationTime(issuedAt + VAPID_TOKEN_SECONDS)
    .setSubject(input.subject)
    .sign(privateKeyOf(input.keys));
  return `vapid t=${token}, k=${vapidPublicKey(input.keys)}`;
}
